export const getAssignmentsUrl = (params: AssignmentsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/v1/vehicles/assignments?${stringifiedParams}` : `/api/v1/vehicles/assignments`
}

export const assignments = async (params: AssignmentsParams, options?: RequestInit): Promise<assignmentsResponse> => {
  
  return customFetch<assignmentsResponse>(getAssignmentsUrl(params),
  {      
    ...options,
    method: 'GET'
    
    
  }
);}





